fn spawn<F, R>(mandatory: bool, f: F) -> Option<sys::Blocking<R>>
where
    F: FnOnce() -> R + Send + 'static,
    R: Send + 'static,
{
    if mandatory {
        sys::spawn_mandatory_blocking(f)
    } else {
        Some(sys::run(f))
    }
}

